import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.plugin.variable.Val;

/** Record on this sheet that the transfer was undone (after the transfer back's own records), then how its figures
 *  moved. */
public class AuditPersonTransferUndone {
    public void audit(@Val TransferInput input, @Val Transfer transfer, @Val Rollup before, Audit audit,
            Rollups rollups) {
        audit.record("PERSON_TRANSFER_UNDONE sheet=" + transfer.fromSheet() + " by=" + input.user() + " name="
                + transfer.name() + " to=" + transfer.toSheet());
        rollups.record(transfer.fromSheet(), input.user(), before);
    }
}
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonRow } from '../../slots/defs/personRow';
import { usePersonError } from './rowError';
import type { Person } from './people';

/** The button that undoes the transfer that brought the person here (a steward only, on the sheet-today they
 *  arrived): they are transferred back to the sheet they came from, and leave the list. */
function PersonTransferUndo({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const { error, setError, begin } = usePersonError(sheetId, person.id);
  const once = useSubmitOnce();

  const undo = useMutation({
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/transfer-undo`, { user }),
    onSuccess: async () => {
      // the person and their claims go back to the sheet they came from: everything shown of both follows
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] }),
        ...(person.origin ? [queryClient.invalidateQueries({ queryKey: ['sheet', person.origin] })] : []),
      ]);
    },
    onError: (e) =>
      setError(e instanceof HttpError && e.body ? e.body : `Could not undo the transfer of ${person.name}.`),
    onSettled: once.done,
  });

  return (
    <td>
      <button
        type="button"
        data-testid="person-transfer-undo"
        disabled={undo.isPending}
        onClick={() => {
          begin();
          if (!once.start()) return;
          undo.mutate();
        }}
      >
        Undo transfer
      </button>
      {error && (
        <p data-testid="person-error" role="alert">
          {error}
        </p>
      )}
    </td>
  );
}

export const contribution = PersonRow.fill({ order: 50, Component: PersonTransferUndo });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { claimsKey } from '../claims/claims';
import { PersonRow } from '../../slots/defs/personRow';
import { usePeople } from './people';
import { usePersonError } from './rowError';
import type { Person } from './people';

/** The picker that merges the person into another (a steward only; not into themselves, neither of them retired).
 *  Their claims, aliases, patrons and pool memberships move to the other, and they leave the list. */
function PersonMerge({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const people = usePeople(sheetId).data ?? [];
  const [chosen, setChosen] = useState('');
  const { error, setError, begin } = usePersonError(sheetId, person.id);
  const once = useSubmitOnce();

  const merge = useMutation({
    mutationFn: (intoId: number) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/merge`, { user, intoId }),
    onSuccess: async () => {
      // the merge moves claims, aliases, patrons and pool members: everything shown of the sheet follows, the
      // claims first so the merged person leaves the list only once the other shows the claims they took
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      await queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
    },
    onError: (e) =>
      setError(e instanceof HttpError && e.body ? e.body : `Could not merge ${person.name}.`),
    onSettled: once.done,
  });

  return (
    <td>
      <select
        data-testid="person-merge-into"
        value={chosen}
        onChange={(e) => {
          setChosen(e.target.value);
          setError('');
        }}
      >
        <option value="">Merge into…</option>
        {people.map((p) => (
          <option key={p.id} value={String(p.id)}>
            {p.name}
          </option>
        ))}
      </select>{' '}
      <button
        type="button"
        data-testid="person-merge"
        disabled={merge.isPending}
        onClick={() => {
          begin();
          if (chosen === '') {
            setError('Choose a person to merge into.');
            return;
          }
          if (!once.start()) return;
          merge.mutate(Number(chosen));
        }}
      >
        Merge
      </button>
      {error && (
        <p data-testid="person-error" role="alert">
          {error}
        </p>
      )}
    </td>
  );
}

export const contribution = PersonRow.fill({ order: 48, Component: PersonMerge });

